const trRoad = (P, pts, w, tn, z = 0.4) => {
  const L = [], R = [];
  for (let i = 0; i < pts.length; i++) {
    const a = pts[Math.max(0, i - 1)], b = pts[Math.min(pts.length - 1, i + 1)], dx = b[0] - a[0], dy = b[1] - a[1], l = Math.hypot(dx, dy) || 1, nx = -dy / l * w / 2, ny = dx / l * w / 2;
    L.push(P.I(pts[i][0] + nx, pts[i][1] + ny, z)); R.push(P.I(pts[i][0] - nx, pts[i][1] - ny, z));
  }
  P.fill(L.concat(R.reverse()), tn);
};
